import { readFileSync } from 'fs'

// Load main caches from temp files (generated by: git show origin/main:src/utils/...)
const dirMainCache = JSON.parse(readFileSync('/tmp/dir_main.json', 'utf-8'))
const distMainCache = JSON.parse(readFileSync('/tmp/dist_main.json', 'utf-8'))

// Load PR caches
const dirPRCache = JSON.parse(readFileSync('src/utils/nomad_cache_table_6857167d82358a0f5e038c3f.json', 'utf-8'))
const distPRCache = JSON.parse(readFileSync('src/utils/nomad_cache_table_68614a111208586bd05d3c3a.json', 'utf-8'))

console.log('='.repeat(80))
console.log('CACHE COMPLETENESS VERIFICATION')
console.log('='.repeat(80))

// Directory table (6857167d82358a0f5e038c3f) consumers
console.log('\n📁 DIRECTORY TABLE (6857167d82358a0f5e038c3f)')
console.log('-'.repeat(80))

// 1. nomad_directory/index.astro - published only
const dirPublished = {
  main: dirMainCache.records.filter(r => r.sf4ad525dd),
  pr: dirPRCache.records.filter(r => r.sf4ad525dd)
}
console.log(`nomad_directory/index.astro (sf4ad525dd):`)
console.log(`  Main: ${dirPublished.main.length} | PR: ${dirPublished.pr.length} ${dirPublished.main.length === dirPublished.pr.length ? '✅' : '❌'}`)

// 2. coworking-contest.astro - reads testimonials (s5716bab58) from directory table
const dirWithTestimonials = {
  main: dirMainCache.records.filter(r => r.s5716bab58),
  pr: dirPRCache.records.filter(r => r.s5716bab58)
}
console.log(`coworking-contest.astro testimonials (s5716bab58):`)
console.log(`  Main: ${dirWithTestimonials.main.length} | PR: ${dirWithTestimonials.pr.length} ${dirWithTestimonials.main.length === dirWithTestimonials.pr.length ? '✅' : '❌'}`)

if (dirWithTestimonials.main.length !== dirWithTestimonials.pr.length) {
  const mainIds = new Set(dirWithTestimonials.main.map(r => r.id))
  const prIds = new Set(dirWithTestimonials.pr.map(r => r.id))
  const missing = [...mainIds].filter(id => !prIds.has(id))
  console.log(`  Missing IDs: ${missing.join(', ')}`)
  
  // Check if missing records are published
  const missingRecords = dirMainCache.records.filter(r => missing.includes(r.id))
  console.log(`  Missing records published status:`)
  missingRecords.forEach(r => console.log(`    ${r.id} (${r.title}): sf4ad525dd=${r.sf4ad525dd}`))
}

// Check field completeness in PR cache
const sampleDirRecord = dirPRCache.records[0]
const dirRequiredFields = ['s5716bab58', 'sd07d77f5e', 'sf4ad525dd', 'title', 'image', 'images', 'sb685ab800']
const dirMissingFields = dirRequiredFields.filter(f => !(f in sampleDirRecord))
if (dirMissingFields.length > 0) {
  console.log(`  ❌ Missing fields in PR directory cache: ${dirMissingFields.join(', ')}`)
} else {
  console.log(`  ✅ All sample required fields present`)
}

// Distribution table (68614a111208586bd05d3c3a) consumers
console.log('\n📦 DISTRIBUTION TABLE (68614a111208586bd05d3c3a)')
console.log('-'.repeat(80))

// 1. distribution-list.astro - s43a4b2808 && title
const distList = {
  main: distMainCache.records.filter(r => r.s43a4b2808 && r.title),
  pr: distPRCache.records.filter(r => r.s43a4b2808 && r.title)
}
console.log(`distribution-list.astro (s43a4b2808 && title):`)
console.log(`  Main: ${distList.main.length} | PR: ${distList.pr.length} ${distList.main.length === distList.pr.length ? '✅' : '❌'}`)

// 2. coworking_directory - s43a4b2808 && title && (category includes 'cowork')
const coworking = {
  main: distMainCache.records.filter(r => {
    if (!r.s43a4b2808 || !r.title) return false
    const cat = (r.sb685ab800?.label || '').toLowerCase()
    return cat.includes('cowork') || cat === 'space' || cat === 'hub'
  }),
  pr: distPRCache.records.filter(r => {
    if (!r.s43a4b2808 || !r.title) return false
    const cat = (r.sb685ab800?.label || '').toLowerCase()
    return cat.includes('cowork') || cat === 'space' || cat === 'hub'
  })
}
console.log(`coworking_directory (s43a4b2808 && title && category):`)
console.log(`  Main: ${coworking.main.length} | PR: ${coworking.pr.length} ${coworking.main.length === coworking.pr.length ? '✅' : '❌'}`)

// 3. coliving_directory - title && category === 'coliving'
const coliving = {
  main: distMainCache.records.filter(r => r.title && (r.sb685ab800?.label || '').toLowerCase() === 'coliving'),
  pr: distPRCache.records.filter(r => r.title && (r.sb685ab800?.label || '').toLowerCase() === 'coliving')
}
console.log(`coliving_directory (title && category='coliving'):`)
console.log(`  Main: ${coliving.main.length} | PR: ${coliving.pr.length} ${coliving.main.length === coliving.pr.length ? '✅' : '❌'}`)

// 4. coworking-contest.astro - category='Coworking' && title && styrldtq === true
const coworkingContest = {
  main: distMainCache.records.filter(r => r.sb685ab800?.label === 'Coworking' && r.title && r.styrldtq === true),
  pr: distPRCache.records.filter(r => r.sb685ab800?.label === 'Coworking' && r.title && r.styrldtq === true)
}
console.log(`coworking-contest.astro (category='Coworking' && title && styrldtq):`)
console.log(`  Main: ${coworkingContest.main.length} | PR: ${coworkingContest.pr.length} ${coworkingContest.main.length === coworkingContest.pr.length ? '✅' : '❌'}`)

if (coworkingContest.main.length !== coworkingContest.pr.length) {
  const mainIds = new Set(coworkingContest.main.map(r => r.id))
  const prIds = new Set(coworkingContest.pr.map(r => r.id))
  const missing = [...mainIds].filter(id => !prIds.has(id))
  console.log(`  Missing: ${missing.length} records`)
  console.log(`  Missing IDs (first 5): ${missing.slice(0, 5).join(', ')}`)
  
  // Check s43a4b2808 status of missing records
  const missingRecords = distMainCache.records.filter(r => missing.includes(r.id))
  const withDistFlag = missingRecords.filter(r => r.s43a4b2808).length
  const withoutDistFlag = missingRecords.filter(r => !r.s43a4b2808).length
  console.log(`  Missing breakdown: ${withDistFlag} with s43a4b2808, ${withoutDistFlag} without`)
}

// 5. newsletter-digital-reading.astro - uses coworking contest filter
console.log(`newsletter-digital-reading.astro (same as coworking-contest):`)
console.log(`  Main: ${coworkingContest.main.length} | PR: ${coworkingContest.pr.length} ${coworkingContest.main.length === coworkingContest.pr.length ? '✅' : '❌'}`)

// 6. editions - sd07d77f5e && title && s43a4b2808
const editions = {
  main: distMainCache.records.filter(r => r.sd07d77f5e && r.title && r.s43a4b2808),
  pr: distPRCache.records.filter(r => r.sd07d77f5e && r.title && r.s43a4b2808)
}
console.log(`editions (sd07d77f5e && title && s43a4b2808):`)
console.log(`  Main: ${editions.main.length} | PR: ${editions.pr.length} ${editions.main.length === editions.pr.length ? '✅' : '❌'}`)

// Check field completeness in PR cache
const sampleDistRecord = distPRCache.records[0]
const distRequiredFields = ['s5716bab58', 'sd07d77f5e', 'styrldtq', 's43a4b2808', 'sf4ad525dd', 'sb685ab800']
const distMissingFields = distRequiredFields.filter(f => !(f in sampleDistRecord))
if (distMissingFields.length > 0) {
  console.log(`  ❌ Missing fields in PR distribution cache: ${distMissingFields.join(', ')}`)
} else {
  console.log(`  ✅ All sample required fields present`)
}

// Summary
console.log('\n' + '='.repeat(80))
console.log('SUMMARY')
console.log('='.repeat(80))

const checks = [
  { name: 'nomad_directory', pass: dirPublished.main.length === dirPublished.pr.length },
  { name: 'directory testimonials', pass: dirWithTestimonials.main.length === dirWithTestimonials.pr.length },
  { name: 'distribution-list', pass: distList.main.length === distList.pr.length },
  { name: 'coworking_directory', pass: coworking.main.length === coworking.pr.length },
  { name: 'coliving_directory', pass: coliving.main.length === coliving.pr.length },
  { name: 'coworking-contest', pass: coworkingContest.main.length === coworkingContest.pr.length },
  { name: 'editions', pass: editions.main.length === editions.pr.length },
]

const allPass = checks.every(c => c.pass)
checks.forEach(c => console.log(`${c.pass ? '✅' : '❌'} ${c.name}`))

console.log(`\n${allPass ? '✅ ALL CHECKS PASSED' : '❌ SOME CHECKS FAILED - see details above'}`)

process.exit(allPass ? 0 : 1)
